var listener = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
listener.Bind(new IPEndPoint(IPAddress.Any, 8080)); listener.Listen(512);

while (true) {
    Socket conn = await listener.AcceptAsync();    // completion-based: no selector thread
    _ = HandleAsync(conn);                         // the handler for this connection
}

static async Task HandleAsync(Socket c) {
    var buf = new byte[4096]; int n;
    while ((n = await c.ReceiveAsync(buf)) > 0) await c.SendAsync(buf.AsMemory(0, n));
}
